program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    row_seps = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_starts = [0] + [r + 1 for r in row_seps]
    row_ends = row_seps + [h]
    col_starts = [0] + [c + 1 for c in col_seps]
    col_ends = col_seps + [w]
    cells = {}
    for ri, (r0, r1) in enumerate(zip(row_starts, row_ends)):
        for ci, (c0, c1) in enumerate(zip(col_starts, col_ends)):
            vals = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1)} - {0}
            for color in vals:
                cells.setdefault(color, []).append((ri, ci))
    paths = {}
    for color, pts in cells.items():
        if len(pts) == 2:
            (r0, c0), (r1, c1) = pts
            path = []
            if r0 == r1:
                path = [(r0, c) for c in range(min(c0,c1), max(c0,c1)+1)]
            elif c0 == c1:
                path = [(r, c0) for r in range(min(r0,r1), max(r0,r1)+1)]
            paths[color] = path
    occupied = {}
    for color, path in paths.items():
        for cell in path:
            occupied.setdefault(cell, []).append(color)
    for (ri, ci), colors in occupied.items():
        fill = 6 if len(colors) > 1 else colors[0]
        r0, r1 = row_starts[ri], row_ends[ri]
        c0, c1 = col_starts[ci], col_ends[ci]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = fill
    return out
